# static sanity: compile every module and check that the pure engine's import closure is numpy-free
import ast, os, sys
mods = {}
for base, dirs, files in os.walk('.'):
    for f in files:
        if f.endswith('.py'):
            path = os.path.join(base, f)
            mod = path[2:-3].replace('/', '.')
            mods[mod] = path
def deps(mod, seen=None):
    seen = seen or set()
    if mod in seen or mod not in mods:
        return seen
    seen.add(mod)
    tree = ast.parse(open(mods[mod]).read())
    for node in ast.walk(tree):
        if isinstance(node, ast.Import):
            for a in node.names:
                if a.name.startswith('netnomos'):
                    deps(a.name, seen)
        elif isinstance(node, ast.ImportFrom):
            if node.module and node.module.startswith('netnomos'):
                deps(node.module, seen)
    return seen
for root in ['netnomos.pypipeline', 'netnomos.nppipeline', 'netnomos.finite']:
    print(root, '->', sorted(deps(root)))
print()
# which modules import numpy at all
for mod, path in sorted(mods.items()):
    src = open(path).read()
    if 'numpy' in src:
        print('numpy referenced in', mod)
PYEOF
